package com.techie345.moneys.financial.liability;
import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import com.techie345.moneys.financial.*; import jakarta.persistence.*;
@Entity @Table(name="liability") public class LiabilityEntity extends FinancialEntity {
 UUID accountId; @Column(nullable=false,length=200) String name; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) LiabilityKind kind; @Column(name="balance_cents",nullable=false) long balanceCents; @Column(name="interest_rate") BigDecimal interestRate; @Column(name="minimum_payment_cents") Long minimumPaymentCents; String source; @Column(name="source_file") String sourceFile; @Column(name="imported_at") Instant importedAt;
 protected LiabilityEntity(){} public LiabilityEntity(UUID o,String n,LiabilityKind k,long b,BigDecimal r,Long p,UUID a,String s,String f,Instant i){if(o==null||n==null||n.isBlank()||k==null||b<=0||p!=null&&p<0)throw new IllegalArgumentException("invalid liability");ownerId=o;name=n;kind=k;balanceCents=b;interestRate=r;minimumPaymentCents=p;accountId=a;source=s;sourceFile=f;importedAt=i;} public UUID getAccountId(){return accountId;} public String getName(){return name;} public LiabilityKind getKind(){return kind;} public long getBalanceCents(){return balanceCents;} public BigDecimal getInterestRate(){return interestRate;} public Long getMinimumPaymentCents(){return minimumPaymentCents;} public String getSource(){return source;} public String getSourceFile(){return sourceFile;} public Instant getImportedAt(){return importedAt;} public void update(String n,LiabilityKind k,long b,BigDecimal r,Long p,UUID a,String s,String f,Instant i){if(n==null||n.isBlank()||k==null||b<=0||p!=null&&p<0)throw new IllegalArgumentException("invalid liability");name=n;kind=k;balanceCents=b;interestRate=r;minimumPaymentCents=p;accountId=a;source=s;sourceFile=f;importedAt=i;}
}
